<script setup lang="ts">import { onMounted,reactive,ref } from 'vue';import{storeToRefs}from'pinia';import{RouterLink}from'vue-router';import AuthorizationSubnav from '../components/AuthorizationSubnav.vue';import{useAuthorizationStore}from'../runtime/authorization-store';const store=useAuthorizationStore();const{rules,options,loading,error,isEmpty,canWrite}=storeToRefs(store);const filters=reactive({keyword:'',planId:''});const actionError=ref<string|null>(null);const weekdays=['一','二','三','四','五','六','日'];const search=()=>store.applyRuleQuery({keyword:filters.keyword||undefined,planId:filters.planId||undefined,pageSize:30});async function remove(id:string){if(!window.confirm('确认删除该授权规则吗？'))return;try{await store.deleteRule(id)}catch(e){actionError.value=e instanceof Error?e.message:'删除失败'}}onMounted(()=>store.load('rules'))</script>
<template><section class="auth-page"><header class="page-header"><div><p class="eyebrow">PRD-003 · 商品授权</p><h1>授权规则</h1><p>每周周期使用 Asia/Shanghai 时区，时段按 [开始,结束) 判断且不允许跨日或重叠。</p></div><RouterLink v-if="canWrite" class="button primary" to="/products/authorizations/rules/new">新增规则</RouterLink></header><AuthorizationSubnav/><form class="filters" @submit.prevent="search"><label><span>规则名称</span><input v-model="filters.keyword"></label><label><span>授权方案</span><select v-model="filters.planId"><option value="">全部方案</option><option v-for="p in store.plans.items" :key="p.id" :value="p.id">{{p.name}}</option></select></label><button class="button primary">查询</button></form><p v-if="actionError" class="warning">{{actionError}}</p><div v-if="error" class="state error">{{error}}</div><div v-else-if="loading" class="state">正在加载授权规则…</div><div v-else-if="isEmpty" class="state"><strong>暂无授权规则</strong></div><div v-else class="table-wrap"><table><thead><tr><th>规则名称</th><th>授权方案</th><th>生效周期</th><th>生效时段</th><th>客户范围</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in rules.items" :key="item.id"><td><RouterLink v-if="canWrite" :to="`/products/authorizations/rules/${item.id}/edit`">{{item.name}}</RouterLink><strong v-else>{{item.name}}</strong></td><td>{{item.planName}}</td><td>每周 {{item.weekdays.map(x=>'周'+weekdays[x-1]).join('、')}}</td><td>{{item.timeRanges.map(x=>`${x.start}～${x.end}`).join('；')}}</td><td>{{item.customerIds.length}} 个客户</td><td>{{item.createdAt.slice(0,16).replace('T',' ')}}</td><td><button v-if="canWrite" class="link danger" @click="remove(item.id)">删除</button><span v-else>只读</span></td></tr></tbody></table></div></section></template><style scoped>@import './authorization-views.css';</style>
